// TEMP review probe — measures selector label wrap heights at widths
// between the 480 lp breakpoint and 720 lp. Deleted after the review run.
import 'dart:io';

import 'package:fa/network/envelope_codec.dart';
import 'package:fa/network/key_wallet.dart';
import 'package:fa/network/models.dart';
import 'package:fa/network/network_session_manager.dart';
import 'package:fa/ui/app_theme.dart';
import 'package:fa/ui/network/add_agent_dialog.dart';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

import 'fakes.dart';
import '../golden/golden_test_helper.dart';

Future<NetworkSessionManager> buildManager({
  required KeyWallet wallet,
}) async => NetworkSessionManager(
  baseUrl: testBase,
  wallet: wallet,
  httpClient: FakeHttpClient(),
  wsConnector: FakeWsConnector(),
  jwtToken: 'jwt',
);

void main() {
  setUpAll(ensureGoldenFonts);

  for (final width in [460.0, 480.0, 500.0, 520.0, 560.0, 600.0, 640.0, 680.0, 720.0]) {
    testWidgets('label heights at $width lp', (tester) async {
      final channelKeys = await EnvelopeCodec.newX25519KeyPair();
      final wallet = await KeyWallet.load(MemoryWalletBackend());
      await wallet.createIfMissing(displayName: 'Me');
      await wallet.addNetwork(networkId: 'net1', name: 'fa-team');
      await wallet.addChannelKeys(
        networkId: 'net1',
        channel: 'c1',
        pub: channelKeys.pub,
        priv: channelKeys.priv,
      );
      tester.view.physicalSize = Size(width, 844);
      tester.view.devicePixelRatio = 1.0;
      addTearDown(tester.view.reset);
      await tester.pumpWidget(
        MaterialApp(
          theme: buildFahTheme(),
          home: Builder(
            builder: (context) => Scaffold(
              body: Center(
                child: TextButton(
                  onPressed: () => showDialog<void>(
                    context: context,
                    builder: (_) => AddAgentDialog(
                      wallet: wallet,
                      manager: await buildManager(wallet: wallet),
                      networkId: 'net1',
                      channel: const Channel(
                        id: 'c1',
                        networkId: 'net1',
                        name: 'general',
                        isPublic: false,
                      ),
                    ),
                  ),
                  child: const Text('open'),
                ),
              ),
            ),
          ),
        ),
      );
      await tester.tap(find.text('open'));
      await tester.pumpAndSettle();

      final rows = <String>[];
      const narrow = width < 480.0;
      for (final label in [
        'DAP',
        'Link (app)',
        'CLI command',
        'Env (CI)',
      ]) {
        final h = tester.getSize(find.text(label)).height;
        rows.add('$label=$h');
      }
      // Also the scope labels when present.
      final scopeHeights = <String>[];
      for (final label in ['This channel', 'Whole network']) {
        final matches = find.text(label);
        if (matches.evaluate().isNotEmpty) {
          scopeHeights.add('$label=${tester.getSize(matches).height}');
        }
      }
      final mode = File('/tmp/probe_mode_${width.toInt()}.txt')
        ..writeAsStringSync(narrow ? 'narrow' : 'wide');
      stdout.writeln(
        'WIDTH=$width mode=${mode.path == '' ? '?' : (narrow ? 'narrow' : 'wide')} '
        'labels: ${rows.join(' ')} scope: ${scopeHeights.join(' ')}',
      );
    });
  }
}

