// TEMP review probe — verifies the 1024 lp breakpoint behavior at the
// boundary and mid-band widths, with the FlutterTest fallback font
// (default) . Deleted after the review run.
import 'package:fa/network/envelope_codec.dart';
import 'package:fa/network/key_wallet.dart';
import 'package:fa/network/models.dart';
import 'package:fa/network/network_session_manager.dart';
import 'package:fa/ui/app_theme.dart';
import 'package:fa/ui/network/add_agent_dialog.dart';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

import 'fakes.dart';

Future<NetworkSessionManager> buildManager({required KeyWallet wallet}) async =>
    NetworkSessionManager(
      baseUrl: testBase,
      wallet: wallet,
      httpClient: FakeHttpClient(),
      wsConnector: FakeWsConnector(),
      jwtToken: 'jwt',
    );

void main() {
  for (final width in [700.0, 768.0, 960.0, 1023.0, 1024.0, 1025.0, 1280.0]) {
    testWidgets('breakpoint behavior at $width lp (FlutterTest font)',
        (tester) async {
      final channelKeys = await EnvelopeCodec.newX25519KeyPair();
      final wallet = await KeyWallet.load(MemoryWalletBackend());
      await wallet.createIfMissing(displayName: 'Me');
      await wallet.addNetwork(networkId: 'net1', name: 'fa-team');
      await wallet.addChannelKeys(
        networkId: 'net1',
        channel: 'c1',
        pub: channelKeys.pub,
        priv: channelKeys.priv,
      );
      final manager = await buildManager(wallet: wallet);
      tester.view.physicalSize = Size(width, 844);
      tester.view.devicePixelRatio = 1.0;
      addTearDown(tester.view.reset);
      await tester.pumpWidget(
        MaterialApp(
          theme: buildFahTheme(),
          home: Builder(
            builder: (context) => Scaffold(
              body: Center(
                child: TextButton(
                  onPressed: () => showDialog<void>(
                    context: context,
                    builder: (_) => AddAgentDialog(
                      wallet: wallet,
                      manager: manager,
                      networkId: 'net1',
                      channel: const Channel(
                        id: 'c1',
                        networkId: 'net1',
                        name: 'general',
                        isPublic: false,
                      ),
                    ),
                  ),
                  child: const Text('open'),
                ),
              ),
            ),
          ),
        ),
      );
      await tester.tap(find.text('open'));
      await tester.pumpAndSettle();

      final chips = tester.widgetList<ChoiceChip>(
        find.byType(ChoiceChip),
      ).length;
      final hasSegments = tester
          .widgetList(find.byKey(const ValueKey('inviteFormat')))
          .isNotEmpty;
      final mode = chips > 0 ? 'chips(narrow)' : 'segments(wide)';
      var labelReport = '';
      if (chips == 0) {
        for (final label in [
          'DAP',
          'Link (app)',
          'CLI command',
          'Env (CI)',
        ]) {
          final h = tester.getSize(find.text(label)).height;
          labelReport += '$label=$h ';
        }
      }
      // ignore: avoid_print
      print('PROBE width=$width mode=$mode chips=$chips segKey=$hasSegments $labelReport');
      expect(tester.takeException(), isNull);
    });
  }
}

